function(container, apiUrl, tables) {
  let currentPredictionData = [];

  // 店舗データを読み込んでドロップダウンに設定
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const storeTable = tables.find(t => t.tableName === '店舗マスタ');
    if (storeTable && storeTable.records) {
      storeTable.records.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 予測結果テーブルの再描画
  function renderPredictionResults(results) {
    const tbody = container.querySelector('#prediction-list-tbody');
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.予測結果ID || ''}">
        <td>${r.商品コード || ''}</td>
        <td>${r.商品名 || ''}</td>
        <td>${r.予測対象日 ? new Date(r.予測対象日).toLocaleDateString() : ''}</td>
        <td>${r.予測数量 || 0}</td>
        <td>${r.予測精度 || 0}%</td>
        <td>${r.推奨発注数量 || 0}</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; 
                       background: ${r.予測ステータス === '完了' ? '#28a745' : r.予測ステータス === 'エラー' ? '#dc3545' : '#ffc107'}; 
                       color: white;">
            ${r.予測ステータス || '未実行'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.予測結果ID || ''}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const loading = container.querySelector('#loading-indicator');
    if (show) {
      loading.classList.remove('hidden');
    } else {
      loading.classList.add('hidden');
    }
  }

  // 予測結果表示制御
  function showResults(show) {
    const results = container.querySelector('#prediction-results');
    if (show) {
      results.classList.remove('hidden');
    } else {
      results.classList.add('hidden');
    }
  }

  // 予測グラフ描画
  function drawPredictionChart(data) {
    const canvas = container.querySelector('#prediction-chart');
    const ctx = canvas.getContext('2d');

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (!data || data.length === 0) return;

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // データの最大値・最小値を計算
    const maxValue = Math.max(...data.map(d => d.value));
    const minValue = Math.min(...data.map(d => d.value));
    const valueRange = maxValue - minValue || 1;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // データポイントを描画
    ctx.strokeStyle = '#4a90e2';
    ctx.lineWidth = 2;
    ctx.beginPath();

    data.forEach((point, index) => {
      const x = padding + (index / (data.length - 1)) * chartWidth;
      const y = padding + chartHeight - ((point.value - minValue) / valueRange) * chartHeight;

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });

    ctx.stroke();

    // タイトル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '16px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('需要予測グラフ', canvas.width / 2, 30);
  }

  // 比較チャート描画
  function drawComparisonChart(actualData, predictedData) {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // 軸を描画
    ctx.strokeStyle = '#9fb0d1';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, padding + chartHeight);
    ctx.lineTo(padding + chartWidth, padding + chartHeight);
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#28a745';
    ctx.fillRect(padding, 10, 15, 15);
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('実績値', padding + 20, 22);

    ctx.fillStyle = '#4a90e2';
    ctx.fillRect(padding + 100, 10, 15, 15);
    ctx.fillText('予測値', padding + 120, 22);

    // タイトル
    ctx.textAlign = 'center';
    ctx.fillText('売上実績 vs 予測値比較', canvas.width / 2, 22);
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const model = container.querySelector('#model-select').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }

    if (!startDate || !endDate) {
      showError('予測期間を設定してください');
      return false;
    }

    if (new Date(startDate) >= new Date(endDate)) {
      showError('開始日は終了日より前の日付を設定してください');
      return false;
    }

    if (new Date(startDate) < new Date()) {
      showError('開始日は本日以降の日付を入力してください');
      return false;
    }

    if (!model) {
      showError('予測モデルが選択されていません。予測モデルを選択してください。');
      return false;
    }

    return true;
  }

  // AI予測実行
  async function executePrediction() {
    if (!validateForm()) return;

    showLoading(true);
    container.querySelector('#error-message').classList.add('hidden');

    try {
      // 予測実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 模擬予測データ生成
      const mockPredictionData = [
        { date: '2024-01-01', value: 120 },
        { date: '2024-01-02', value: 135 },
        { date: '2024-01-03', value: 98 },
        { date: '2024-01-04', value: 156 },
        { date: '2024-01-05', value: 142 }
      ];

      currentPredictionData = [{
        予測結果ID: 'pred-001',
        商品コード: container.querySelector('#product-code').value || 'PROD001',
        商品名: 'サンプル商品',
        予測対象日: container.querySelector('#start-date').value,
        予測数量: 1250,
        予測精度: 85,
        推奨発注数量: 1300,
        予測ステータス: '完了'
      }];

      // 予測結果を需要予測結果テーブルに保存
      const predictionResult = {
        店舗ID: container.querySelector('#store-select').value,
        商品ID: 'sample-product-id',
        予測対象日: container.querySelector('#start-date').value,
        予測数量: 1250,
        予測精度: 85,
        推奨発注数量: 1300,
        予測モデルバージョン: 'v1.0',
        予測ステータス: '完了',
        発注済フラグ: false,
        備考: 'AI自動予測'
      };

      const saved = await window.aivicApi.save(6, predictionResult); // 需要予測結果テーブルのインデックス

      // UI更新
      showLoading(false);
      showResults(true);
      renderPredictionResults(currentPredictionData);
      drawPredictionChart(mockPredictionData);
      drawComparisonChart([], mockPredictionData);

      // 精度指標更新
      container.querySelector('#accuracy-score').textContent = '85%';
      container.querySelector('#confidence-interval').textContent = '±12%';
      container.querySelector('#error-rate').textContent = '8.5%';

      // 影響要因分析結果更新
      container.querySelector('#factor-analysis').innerHTML = `
        <div style="margin-bottom: 10px;">
          <strong>主要影響要因:</strong>
          <ul style="margin: 5px 0 0 20px;">
            <li>季節性要因: 影響度 高 (係数: 1.2)</li>
            <li>天候要因: 影響度 中 (係数: 0.8)</li>
            <li>曜日要因: 影響度 中 (係数: 1.1)</li>
          </ul>
        </div>
      `;

      // 天候・イベント情報更新
      container.querySelector('#weather-info').innerHTML = `
        <p><strong>予測期間平均気温:</strong> 15°C</p>
        <p><strong>降水確率:</strong> 30%</p>
        <p><strong>天候傾向:</strong> 晴れ時々曇り</p>
      `;

      container.querySelector('#event-info').innerHTML = `
        <p><strong>期間中のイベント:</strong> 2件</p>
        <p>・地域祭り (影響度: 中)</p>
        <p>・セール期間 (影響度: 高)</p>
      `;

    } catch (error) {
      showLoading(false);
      showError('AI予測処理中にエラーが発生しました。しばらく時間をおいて再度実行してください。');
    }
  }

  // CSVエクスポート
  function exportResults() {
    if (currentPredictionData.length === 0) {
      showError('エクスポートする予測結果がありません');
      return;
    }

    const headers = ['商品コード', '商品名', '予測期間', '予測数量', '予測精度', '推奨発注数量', 'ステータス'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...currentPredictionData.map(row => [
        row.商品コード || '',
        row.商品名 || '',
        row.予測対象日 ? new Date(row.予測対象日).toLocaleDateString() : '',
        row.予測数量 || 0,
        (row.予測精度 || 0) + '%',
        row.推奨発注数量 || 0,
        row.予測ステータス || ''
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `需要予測結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  loadStores();

  // 初期データ読み込み
  window.aivicApi.list(6).then(rows => {
    if (rows) {
      renderPredictionResults(rows);
    }
  });

  // イベントリスナー
  container.querySelector('#btn-execute-prediction').addEventListener('click', executePrediction);
  container.querySelector('#btn-export-results').addEventListener('click', exportResults);

  // 行レベル操作
  container.addEventListener('click', async (e) => {
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細画面への遷移
      window.showScreen('scr-1778591885672'); // AI需要予測処理画面
    }
  });

  // デフォルト日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);

  container.querySelector('#start-date').value = tomorrow.toISOString().split('T')[0];
  container.querySelector('#end-date').value = nextWeek.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allHistories = [];
  let filteredHistories = [];
  let users = [];

  // ユーザー一覧を取得してセレクトボックスに設定
  async function loadUsers() {
    try {
      const userRows = await window.aivicApi.list(0); // ログインユーザーテーブル
      if (userRows) {
        users = userRows;
        const userSelect = container.querySelector("#select-user");
        userSelect.innerHTML = '<option value="">すべてのユーザー</option>';
        userRows.forEach(user => {
          userSelect.innerHTML += `<option value="${user.ユーザーID}">${user.ユーザー名}</option>`;
        });
      }
    } catch (error) {
      console.error('ユーザー一覧の取得に失敗しました:', error);
    }
  }

  // 操作履歴テーブルの再描画
  function renderHistories(histories) {
    const tbody = container.querySelector("#history-table-body");
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageHistories = histories.slice(startIndex, endIndex);

    tbody.innerHTML = pageHistories.map(history => {
      const user = users.find(u => u.ユーザーID === history.ユーザーID);
      const userName = user ? user.ユーザー名 : '不明';
      const operationDate = new Date(history.操作日時).toLocaleString('ja-JP');

      return `
        <tr data-id="${history.操作履歴ID}">
          <td>${operationDate}</td>
          <td>${userName}</td>
          <td>${history.操作種別 || ''}</td>
          <td>${history.操作画面 || ''}</td>
          <td>${history.IPアドレス || ''}</td>
          <td>
            <span style="padding: 2px 8px; border-radius: 4px; font-size: 12px; 
              ${history.処理結果 === '成功' ? 'background: rgba(34, 197, 94, 0.1); color: #22c55e;' : 
                history.処理結果 === '失敗' || history.処理結果 === 'エラー' ? 'background: rgba(239, 68, 68, 0.1); color: #ef4444;' : 
                'background: rgba(156, 163, 175, 0.1); color: #9ca3af;'}">
              ${history.処理結果 || ''}
            </span>
          </td>
          <td>${history.処理時間 || ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${history.操作履歴ID}">詳細</button>
          </td>
        </tr>
      `;
    }).join('');

    // 結果件数とページ情報を更新
    container.querySelector("#result-count").textContent = `${histories.length}件の履歴が見つかりました`;

    const totalPages = Math.ceil(histories.length / itemsPerPage);
    container.querySelector("#page-info").textContent = `${currentPage} / ${totalPages} ページ`;

    // ページネーションボタンの状態更新
    container.querySelector("#btn-prev").disabled = currentPage <= 1;
    container.querySelector("#btn-next").disabled = currentPage >= totalPages;
  }

  // 初期データの読み込み
  async function loadHistories() {
    try {
      const rows = await window.aivicApi.list(12); // システム操作履歴テーブル
      if (rows) {
        allHistories = rows.sort((a, b) => new Date(b.操作日時) - new Date(a.操作日時));
        filteredHistories = [...allHistories];
        renderHistories(filteredHistories);
      }
    } catch (error) {
      console.error('操作履歴の取得に失敗しました:', error);
    }
  }

  // 検索フィルター処理
  function applyFilters() {
    const dateStart = container.querySelector("#input-date-start").value;
    const dateEnd = container.querySelector("#input-date-end").value;
    const userId = container.querySelector("#select-user").value;
    const operationType = container.querySelector("#select-operation-type").value;
    const screenName = container.querySelector("#input-screen-name").value.toLowerCase();
    const ipAddress = container.querySelector("#input-ip-address").value;
    const result = container.querySelector("#select-result").value;

    // 日付範囲の妥当性チェック
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      alert('開始日は終了日より前の日付を入力してください');
      return;
    }

    // IPアドレス形式の妥当性チェック
    if (ipAddress && !isValidIP(ipAddress)) {
      alert('正しいIPアドレス形式で入力してください');
      return;
    }

    filteredHistories = allHistories.filter(history => {
      // 日付範囲フィルター
      if (dateStart && new Date(history.操作日時) < new Date(dateStart)) return false;
      if (dateEnd && new Date(history.操作日時) > new Date(dateEnd + 'T23:59:59')) return false;

      // ユーザーフィルター
      if (userId && history.ユーザーID !== userId) return false;

      // 操作種別フィルター
      if (operationType && history.操作種別 !== operationType) return false;

      // 画面名・機能名フィルター
      if (screenName && !(history.操作画面 || '').toLowerCase().includes(screenName)) return false;

      // IPアドレスフィルター
      if (ipAddress && !(history.IPアドレス || '').includes(ipAddress)) return false;

      // 処理結果フィルター
      if (result && history.処理結果 !== result) return false;

      return true;
    });

    currentPage = 1;
    renderHistories(filteredHistories);
  }

  // IPアドレス形式の妥当性チェック
  function isValidIP(ip) {
    // IPv4の正規表現
    const ipv4Regex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
    // IPv6の簡易正規表現
    const ipv6Regex = /^(?:[0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$/;

    return ipv4Regex.test(ip) || ipv6Regex.test(ip);
  }

  // 検索条件クリア
  function clearFilters() {
    container.querySelector("#input-date-start").value = '';
    container.querySelector("#input-date-end").value = '';
    container.querySelector("#select-user").value = '';
    container.querySelector("#select-operation-type").value = '';
    container.querySelector("#input-screen-name").value = '';
    container.querySelector("#input-ip-address").value = '';
    container.querySelector("#select-result").value = '';

    filteredHistories = [...allHistories];
    currentPage = 1;
    renderHistories(filteredHistories);
  }

  // CSV出力
  function exportCSV() {
    if (filteredHistories.length === 0) {
      alert('出力可能なデータがありません');
      return;
    }

    const headers = ['操作日時', 'ユーザー名', '操作種別', '操作画面', '操作対象テーブル', '操作対象ID', '操作内容', 'IPアドレス', 'ユーザーエージェント', '処理結果', 'エラーメッセージ', '処理時間'];

    const csvContent = [
      headers.join(','),
      ...filteredHistories.map(history => {
        const user = users.find(u => u.ユーザーID === history.ユーザーID);
        const userName = user ? user.ユーザー名 : '不明';

        return [
          `"${new Date(history.操作日時).toLocaleString('ja-JP')}"`,
          `"${userName}"`,
          `"${history.操作種別 || ''}"`,
          `"${history.操作画面 || ''}"`,
          `"${history.操作対象テーブル || ''}"`,
          `"${history.操作対象ID || ''}"`,
          `"${(history.操作内容 || '').replace(/"/g, '""')}"`,
          `"${history.IPアドレス || ''}"`,
          `"${(history.ユーザーエージェント || '').replace(/"/g, '""')}"`,
          `"${history.処理結果 || ''}"`,
          `"${(history.エラーメッセージ || '').replace(/"/g, '""')}"`,
          `"${history.処理時間 || ''}"`
        ].join(',');
      })
    ].join('\n');

    const bom = '\uFEFF';
    const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `操作履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 詳細モーダル表示
  function showDetailModal(historyId) {
    const history = allHistories.find(h => h.操作履歴ID === historyId);
    if (!history) return;

    const user = users.find(u => u.ユーザーID === history.ユーザーID);
    const userName = user ? user.ユーザー名 : '不明';

    container.querySelector("#detail-id").textContent = history.操作履歴ID || '';
    container.querySelector("#detail-datetime").textContent = new Date(history.操作日時).toLocaleString('ja-JP');
    container.querySelector("#detail-user").textContent = userName;
    container.querySelector("#detail-operation").textContent = history.操作種別 || '';
    container.querySelector("#detail-screen").textContent = history.操作画面 || '';
    container.querySelector("#detail-table").textContent = history.操作対象テーブル || '';
    container.querySelector("#detail-target-id").textContent = history.操作対象ID || '';
    container.querySelector("#detail-ip").textContent = history.IPアドレス || '';
    container.querySelector("#detail-user-agent").textContent = history.ユーザーエージェント || '';
    container.querySelector("#detail-result").textContent = history.処理結果 || '';
    container.querySelector("#detail-time").textContent = history.処理時間 ? `${history.処理時間}ms` : '';
    container.querySelector("#detail-content").textContent = history.操作内容 || '';
    container.querySelector("#detail-error").textContent = history.エラーメッセージ || '';

    container.querySelector("#detail-modal").classList.remove('hidden');
  }

  // イベントリスナーの設定
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-clear").addEventListener("click", clearFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  // ページネーション
  container.querySelector("#btn-prev").addEventListener("click", () => {
    if (currentPage > 1) {
      currentPage--;
      renderHistories(filteredHistories);
    }
  });

  container.querySelector("#btn-next").addEventListener("click", () => {
    const totalPages = Math.ceil(filteredHistories.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderHistories(filteredHistories);
    }
  });

  // モーダル関連
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#detail-modal").classList.add('hidden');
  });

  container.querySelector("#detail-modal").addEventListener("click", (e) => {
    if (e.target.id === 'detail-modal') {
      container.querySelector("#detail-modal").classList.add('hidden');
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetailModal(detailBtn.dataset.id);
    }
  });

  // 初期化
  loadUsers().then(() => {
    loadHistories();
  });
}

function(container, apiUrl, tables) {
  let selectedProduct = null;
  let currentForecastData = null;

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 店舗データ読み込み
  async function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const stores = await window.aivicApi.list(1); // 店舗マスタ
    if (stores) {
      stores.forEach(store => {
        if (store.有効フラグ) {
          const option = document.createElement('option');
          option.value = store.店舗ID;
          option.textContent = `${store.店舗名} (${store.店舗コード})`;
          storeSelect.appendChild(option);
        }
      });
    }
  }

  // 商品一覧描画
  function renderProducts(products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = products.map(product => `
      <tr data-id="${product.商品ID}" class="product-row">
        <td><input type="radio" name="selected-product" value="${product.商品ID}" class="product-radio"></td>
        <td>${product.商品コード || ''}</td>
        <td>${product.商品名 || ''}</td>
        <td>${product.商品カテゴリID || ''}</td>
        <td><input type="number" class="input current-stock-input" min="0" value="0" style="width: 80px;"></td>
        <td class="forecast-cell">-</td>
        <td class="ai-recommended-cell">-</td>
      </tr>
    `).join('');
  }

  // 商品絞り込み
  async function filterProducts() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const searchText = container.querySelector('#product-search').value.toLowerCase();

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    const products = await window.aivicApi.list(2); // 商品マスタ
    if (!products) return;

    let filtered = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);

    if (category) {
      filtered = filtered.filter(p => p.商品カテゴリID === category);
    }

    if (searchText) {
      filtered = filtered.filter(p => 
        (p.商品名 || '').toLowerCase().includes(searchText) ||
        (p.商品コード || '').toLowerCase().includes(searchText)
      );
    }

    renderProducts(filtered);
  }

  // 需要予測更新
  async function updateForecast() {
    const storeId = container.querySelector('#store-select').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    if (!storeId || !startDate || !endDate) {
      showError('店舗と対象期間を設定してください');
      return;
    }

    if (new Date(startDate) > new Date() && new Date(endDate) > new Date()) {
      showError('対象期間に過去または現在の日付を含めてください');
      return;
    }

    // 需要予測結果を取得
    const forecasts = await window.aivicApi.list(8); // 需要予測結果
    if (!forecasts) return;

    const storeForecasts = forecasts.filter(f => 
      f.店舗ID === storeId && 
      f.予測対象日 >= startDate && 
      f.予測対象日 <= endDate
    );

    // 商品行に予測結果を反映
    const productRows = container.querySelectorAll('.product-row');
    productRows.forEach(row => {
      const productId = row.dataset.id;
      const productForecasts = storeForecasts.filter(f => f.商品ID === productId);

      if (productForecasts.length > 0) {
        const totalForecast = productForecasts.reduce((sum, f) => sum + (f.予測数量 || 0), 0);
        const avgRecommended = Math.round(productForecasts.reduce((sum, f) => sum + (f.推奨発注数量 || 0), 0) / productForecasts.length);

        row.querySelector('.forecast-cell').textContent = totalForecast;
        row.querySelector('.ai-recommended-cell').textContent = avgRecommended;
      }
    });

    currentForecastData = storeForecasts;
  }

  // 商品選択処理
  function selectProduct(productId) {
    const productRow = container.querySelector(`tr[data-id="${productId}"]`);
    if (!productRow) return;

    selectedProduct = {
      id: productId,
      code: productRow.children[1].textContent,
      name: productRow.children[2].textContent,
      category: productRow.children[3].textContent,
      currentStock: parseInt(productRow.querySelector('.current-stock-input').value) || 0,
      forecast: parseInt(productRow.querySelector('.forecast-cell').textContent) || 0,
      aiRecommended: parseInt(productRow.querySelector('.ai-recommended-cell').textContent) || 0
    };

    // 詳細エリア表示
    const detailArea = container.querySelector('#calculation-detail');
    const productInfo = container.querySelector('#selected-product-info');

    productInfo.innerHTML = `
      <h4>${selectedProduct.name}</h4>
      <p class="muted">商品コード: ${selectedProduct.code} | カテゴリ: ${selectedProduct.category}</p>
    `;

    // フィールドに初期値設定
    container.querySelector('#current-stock').value = selectedProduct.currentStock;
    container.querySelector('#safety-stock').value = 0;
    container.querySelector('#lead-time').value = 7;
    container.querySelector('#weather-impact').value = '1.0';
    container.querySelector('#event-impact').value = 0;
    container.querySelector('#seasonal-factor').value = 1.0;

    detailArea.style.display = 'block';
  }

  // 発注量計算
  function calculateOrder() {
    if (!selectedProduct) {
      showError('商品を選択してください');
      return;
    }

    const currentStock = parseInt(container.querySelector('#current-stock').value) || 0;
    const safetyStock = parseInt(container.querySelector('#safety-stock').value) || 0;
    const leadTime = parseInt(container.querySelector('#lead-time').value) || 7;
    const weatherImpact = parseFloat(container.querySelector('#weather-impact').value) || 1.0;
    const eventImpact = parseInt(container.querySelector('#event-impact').value) || 0;
    const seasonalFactor = parseFloat(container.querySelector('#seasonal-factor').value) || 1.0;

    // バリデーション
    if (currentStock < 0) {
      showError('現在在庫数は0以上の値を入力してください');
      return;
    }
    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫は数値を入力してください');
      return;
    }
    if (leadTime < 1 || leadTime > 365) {
      showError('リードタイムは1-365日の範囲で入力してください');
      return;
    }
    if (eventImpact < 0 || eventImpact > 100) {
      showError('イベント影響度は0-100%の範囲で入力してください');
      return;
    }
    if (seasonalFactor < 0) {
      showError('季節補正係数は0以上の値を入力してください');
      return;
    }

    // 計算実行
    const baseForecast = selectedProduct.forecast;
    const adjustedForecast = Math.round(baseForecast * weatherImpact * (1 + eventImpact / 100) * seasonalFactor);
    const leadTimeDemand = Math.round(adjustedForecast * leadTime / 30); // 月次予測を日次に変換
    const aiRecommended = Math.max(0, adjustedForecast + safetyStock + leadTimeDemand - currentStock);

    // 結果表示
    container.querySelector('#forecast-result').textContent = `${adjustedForecast}個`;
    container.querySelector('#ai-recommended').textContent = `${aiRecommended}個`;
    container.querySelector('#manual-adjustment').placeholder = aiRecommended;

    // 計算内訳表示
    const breakdown = `
基準需要予測: ${baseForecast}個
天候影響調整: ${baseForecast} × ${weatherImpact} = ${Math.round(baseForecast * weatherImpact)}個
イベント影響調整: +${eventImpact}% = ${Math.round(baseForecast * weatherImpact * (1 + eventImpact / 100))}個
季節補正: × ${seasonalFactor} = ${adjustedForecast}個
リードタイム需要: ${leadTimeDemand}個 (${leadTime}日分)
安全在庫: ${safetyStock}個
現在在庫: ${currentStock}個

AI推奨発注量 = ${adjustedForecast} + ${safetyStock} + ${leadTimeDemand} - ${currentStock} = ${aiRecommended}個
    `;

    container.querySelector('#calculation-breakdown').textContent = breakdown;
    container.querySelector('#calculation-result').style.display = 'block';
    container.querySelector('#btn-create-order').style.display = 'inline-block';
  }

  // 手動調整処理
  function handleManualAdjustment() {
    const manualValue = parseInt(container.querySelector('#manual-adjustment').value);
    if (manualValue !== undefined && manualValue < 0) {
      showError('手動調整値は0以上の値を入力してください');
      container.querySelector('#manual-adjustment').value = '';
      return;
    }
  }

  // 現在在庫数変更時の再計算
  function handleStockChange() {
    const newStock = parseInt(container.querySelector('#current-stock').value) || 0;
    if (selectedProduct) {
      selectedProduct.currentStock = newStock;
      if (container.querySelector('#calculation-result').style.display !== 'none') {
        calculateOrder();
      }
    }
  }

  // 初期化
  loadStores();

  // デフォルト期間設定（過去30日から今日まで）
  const today = new Date();
  const thirtyDaysAgo = new Date(today);
  thirtyDaysAgo.setDate(today.getDate() - 30);

  container.querySelector('#period-start').value = thirtyDaysAgo.toISOString().split('T')[0];
  container.querySelector('#period-end').value = today.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#btn-filter').addEventListener('click', filterProducts);
  container.querySelector('#btn-update-forecast').addEventListener('click', updateForecast);
  container.querySelector('#btn-calculate').addEventListener('click', calculateOrder);
  container.querySelector('#current-stock').addEventListener('input', handleStockChange);
  container.querySelector('#manual-adjustment').addEventListener('input', handleManualAdjustment);

  // 商品選択
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-radio')) {
      selectProduct(e.target.value);
    }
  });

  // 在庫数変更
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('current-stock-input')) {
      const row = e.target.closest('tr');
      const productId = row.dataset.id;
      if (selectedProduct && selectedProduct.id === productId) {
        selectedProduct.currentStock = parseInt(e.target.value) || 0;
      }
    }
  });

  // 画面遷移
  container.querySelector('#btn-create-order').addEventListener('click', () => {
    const finalOrder = parseInt(container.querySelector('#manual-adjustment').value) || 
                      parseInt(container.querySelector('#ai-recommended').textContent);

    // 発注データを保存
    const orderData = {
      店舗ID: container.querySelector('#store-select').value,
      商品ID: selectedProduct.id,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + parseInt(container.querySelector('#lead-time').value) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: finalOrder,
      予測数量: parseInt(container.querySelector('#forecast-result').textContent),
      発注単価: 0, // 商品マスタから取得が必要
      発注金額: 0,
      発注方法: container.querySelector('#manual-adjustment').value ? 'AI推奨修正' : 'AI推奨採用',
      発注ステータス: '発注済',
      自動発注フラグ: false,
      作成者ID: 'current-user', // 実際のユーザーIDが必要
      更新者ID: 'current-user'
    };

    window.aivicApi.save(9, orderData).then(() => {
      window.showScreen('scr-1778591907544'); // 発注書作成画面
    });
  });

  container.querySelector('#btn-back-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1778591780173');
  });

  // 初期商品一覧読み込み
  filterProducts();
}

function(container, apiUrl, tables) {
  let selectedProducts = [];
  let allProducts = [];
  let allStores = [];
  let demandPredictions = {};

  // 初期化
  async function initialize() {
    try {
      // 店舗データ取得
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      allStores = stores || [];
      renderStoreOptions();

      // 商品データ取得
      const products = await window.aivicApi.list(2); // 商品マスタ
      allProducts = products || [];
      renderCategoryOptions();
      renderProductList(allProducts);

      // 需要予測データ取得
      const predictions = await window.aivicApi.list(9); // 需要予測結果
      if (predictions) {
        predictions.forEach(p => {
          const key = `${p.店舗ID}_${p.商品ID}`;
          demandPredictions[key] = p;
        });
      }

      // 今日の日付を発注日にセット
      const today = new Date().toISOString().split('T')[0];
      container.querySelector('#order-date').value = today;

    } catch (error) {
      console.error('初期化エラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    allStores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // カテゴリ選択肢を描画
  function renderCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    const categories = [...new Set(allProducts.map(p => p.商品カテゴリID))];
    categorySelect.innerHTML = '<option value="">全カテゴリ</option>';
    categories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId}</option>`;
      }
    });
  }

  // 商品一覧を描画
  function renderProductList(products) {
    const tbody = container.querySelector('#product-list-tbody');
    const storeId = container.querySelector('#store-select').value;

    tbody.innerHTML = products.map(product => {
      if (!product.有効フラグ) return '';

      const predictionKey = `${storeId}_${product.商品ID}`;
      const prediction = demandPredictions[predictionKey];
      const predictedQty = prediction ? prediction.予測数量 : 0;

      return `
        <tr data-product-id="${product.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.単価 ? product.単価.toLocaleString() : 0}円</td>
          <td><span class="inventory-status" data-product-id="${product.商品ID}">確認中</span></td>
          <td><span class="ai-prediction">${predictedQty}</span></td>
          <td><input type="number" class="input manual-qty" min="0" value="${predictedQty}" style="width: 80px;"></td>
          <td><button class="action-btn secondary prediction-basis-btn" data-product-id="${product.商品ID}">根拠表示</button></td>
          <td><button class="action-btn add-product-btn" data-product-id="${product.商品ID}">追加</button></td>
        </tr>
      `;
    }).join('');
  }

  // 選択商品一覧を描画
  function renderSelectedProducts() {
    const tbody = container.querySelector('#selected-products-tbody');
    tbody.innerHTML = selectedProducts.map(item => {
      const subtotal = item.quantity * item.price;
      return `
        <tr data-selected-id="${item.productId}">
          <td>${item.productCode}</td>
          <td>${item.productName}</td>
          <td>${item.quantity}</td>
          <td>${item.price.toLocaleString()}円</td>
          <td>${subtotal.toLocaleString()}円</td>
          <td><button class="action-btn secondary remove-product-btn" data-product-id="${item.productId}">削除</button></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // 発注総額を更新
  function updateTotalAmount() {
    const total = selectedProducts.reduce((sum, item) => sum + (item.quantity * item.price), 0);
    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      showError('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      showError('納期を指定してください');
      return false;
    }

    const today = new Date().toISOString().split('T')[0];
    if (orderDate < today) {
      showError('発注日に過去の日付は設定できません');
      return false;
    }

    if (deliveryDate < orderDate) {
      showError('納期は発注日以降の日付を設定してください');
      return false;
    }

    if (selectedProducts.length === 0) {
      showError('商品を選択してください');
      return false;
    }

    return true;
  }

  // 商品検索
  container.querySelector('#btn-search-product').addEventListener('click', () => {
    const searchTerm = container.querySelector('#product-search').value.toLowerCase();
    const categoryId = container.querySelector('#category-select').value;

    let filteredProducts = allProducts;

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    if (searchTerm) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.toLowerCase().includes(searchTerm)) ||
        (p.商品コード && p.商品コード.toLowerCase().includes(searchTerm))
      );
    }

    if (filteredProducts.length === 0 && searchTerm) {
      showError('該当する商品が見つかりませんでした');
    }

    renderProductList(filteredProducts);
  });

  // カテゴリ選択時の商品一覧更新
  container.querySelector('#category-select').addEventListener('change', () => {
    container.querySelector('#btn-search-product').click();
  });

  // 店舗選択時の予測数量更新
  container.querySelector('#store-select').addEventListener('change', () => {
    renderProductList(allProducts);
  });

  // 商品追加
  container.addEventListener('click', (e) => {
    const addBtn = e.target.closest('.add-product-btn');
    if (addBtn) {
      const productId = addBtn.dataset.productId;
      const row = addBtn.closest('tr');
      const manualQty = parseInt(row.querySelector('.manual-qty').value) || 0;

      if (manualQty < 0) {
        showError('手動調整数量は0以上の値を入力してください');
        return;
      }

      const product = allProducts.find(p => p.商品ID === productId);
      if (product) {
        // 既に選択済みかチェック
        const existingIndex = selectedProducts.findIndex(p => p.productId === productId);
        if (existingIndex >= 0) {
          selectedProducts[existingIndex].quantity = manualQty;
        } else {
          selectedProducts.push({
            productId: product.商品ID,
            productCode: product.商品コード,
            productName: product.商品名,
            quantity: manualQty,
            price: product.単価 || 0
          });
        }
        renderSelectedProducts();
      }
    }
  });

  // 商品削除
  container.addEventListener('click', (e) => {
    const removeBtn = e.target.closest('.remove-product-btn');
    if (removeBtn) {
      const productId = removeBtn.dataset.productId;
      selectedProducts = selectedProducts.filter(p => p.productId !== productId);
      renderSelectedProducts();
    }
  });

  // 予測根拠表示
  container.addEventListener('click', (e) => {
    const basisBtn = e.target.closest('.prediction-basis-btn');
    if (basisBtn) {
      const productId = basisBtn.dataset.productId;
      const storeId = container.querySelector('#store-select').value;
      const predictionKey = `${storeId}_${productId}`;
      const prediction = demandPredictions[predictionKey];

      const modal = container.querySelector('#prediction-modal');
      const details = container.querySelector('#prediction-details');

      if (prediction) {
        details.innerHTML = `
          <div style="margin-bottom: 1rem;">
            <h4>予測詳細情報</h4>
            <p><strong>予測数量:</strong> ${prediction.予測数量}</p>
            <p><strong>予測精度:</strong> ${prediction.予測精度 || 'N/A'}%</p>
            <p><strong>推奨発注数量:</strong> ${prediction.推奨発注数量 || 'N/A'}</p>
            <p><strong>予測モデルバージョン:</strong> ${prediction.予測モデルバージョン || 'N/A'}</p>
            <p><strong>備考:</strong> ${prediction.備考 || '特記事項なし'}</p>
          </div>
          <div>
            <h4>予測根拠</h4>
            <ul>
              <li>過去3ヶ月の売上実績データを基に算出</li>
              <li>季節性要因を考慮した補正</li>
              <li>曜日・祝日による需要変動を反映</li>
              <li>天候データとの相関分析結果を適用</li>
            </ul>
          </div>
        `;
      } else {
        details.innerHTML = '<p>この商品の予測データがありません。</p>';
      }

      modal.classList.remove('hidden');
    }
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });

  // 在庫状況確認
  container.querySelector('#btn-check-inventory').addEventListener('click', async () => {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    // 在庫状況を更新（実際のAPIがあれば呼び出し）
    const inventoryElements = container.querySelectorAll('.inventory-status');
    inventoryElements.forEach(element => {
      const productId = element.dataset.productId;
      // ダミーデータで在庫状況を表示
      const randomStock = Math.floor(Math.random() * 100);
      let status = '十分';
      let color = '#28a745';

      if (randomStock < 10) {
        status = '欠品';
        color = '#dc3545';
      } else if (randomStock < 30) {
        status = '不足';
        color = '#ffc107';
      }

      element.textContent = `${randomStock}個 (${status})`;
      element.style.color = color;
    });
  });

  // 過去実績参照
  container.querySelector('#btn-view-history').addEventListener('click', () => {
    const modal = container.querySelector('#history-modal');
    modal.classList.remove('hidden');
  });

  container.querySelector('#btn-close-history-modal').addEventListener('click', () => {
    container.querySelector('#history-modal').classList.add('hidden');
  });

  container.querySelector('#btn-get-history').addEventListener('click', async () => {
